    description: [
      { type: "paragraph", html: "<p>The only thing that matters in a pen pot is whether it tips when you pull a pen out with one hand. Most fail, because they are straight-sided cylinders with no weight at the base. You reach for a pen, the pot comes with it, and everything scatters.</p><p>So the base here is 9 cm across against a 10 cm rim, which puts the weight low, and the weave at the bottom is doubled. It is a small change that makes the difference between a pot you use and one you stop trusting.</p>" },
      { type: "heading", level: 3, text: "How much it holds" },
      { type: "paragraph", html: "<p>About twenty pens or pencils at a comfortable density. Any more and they lean on each other and you cannot see what you are reaching for, which defeats the point of an open pot.</p>" },
      { type: "list", items: ["Wider base so it will not tip", "Doubled weave at the bottom for weight", "Holds about twenty pens without crowding", "Works for brushes and scissors too"] },
      { type: "table", head: ["Detail", "Specification"], rows: [["Height", "11 cm"], ["Opening", "10 cm"], ["Base", "9 cm, doubled weave"], ["Capacity", "About 20 pens"], ["Finish", "Untreated natural leaf"]] },
      { type: "notice", tone: "info", text: "Do not put wet brushes straight into it. Water in the base will soften the doubled weave, which is the part doing the work of keeping it upright." },
      { type: "quote", text: "A pen pot that tips is a pen pot you stop using. The base width is the whole design." },
      { type: "paragraph", html: "<p>Wipe it out occasionally and it will sit on the same desk for years. The straw darkens slowly, which suits a working desk better than a pristine finish would.</p>" },
    ],
    images: ["woven-pen-pot"],
